-- Migração 32 (cw_nonprod): carteira de investimentos (ativos, preços oficiais, índices, movimentações, benchmark, alocação recomendada). Cole no SQL Editor e execute.
begin;
-- GENERATED by scripts/gen-migrations.mjs from supabase/templates. Do not edit by hand.
-- Gate 23 (D-057): investment portfolio — instruments, official prices and indices, movements, benchmark and the
-- office's recommended allocation. Additive.
-- Market data (official prices, indices, platform-wide instruments) is public information shared by every office.
-- Products an office creates (bank deposits on the curve, COE, manual prices) belong to that office only. Movements
-- belong to the client and follow can_access_client (office, consultant assignment, client portal read-only).

-- ---------------------------------------------------------------- instruments
create table cw_nonprod.instruments (
  id             uuid primary key default gen_random_uuid(),
  office_id      uuid references cw_nonprod.offices (id) on delete cascade, -- null = platform-wide (official source)
  kind           text not null check (kind in ('BANK_FI', 'PRIVATE_CREDIT', 'TREASURY', 'FUND', 'PENSION', 'EQUITY', 'CRYPTO',
                                               'FOREIGN_EQUITY', 'FOREIGN_FUND', 'BOND', 'CUSTOM')),
  subclass       text check (length(subclass) <= 40),
  code           text not null check (code ~ '^[A-Z0-9][A-Z0-9.+/_-]{1,39}$'),
  name           text not null check (length(btrim(name)) between 1 and 160),
  issuer         text check (length(issuer) <= 120),
  currency       char(3) not null default 'BRL' check (currency in ('BRL', 'USD', 'EUR')),
  pricing        text not null check (pricing in ('MARKET', 'CURVE', 'MANUAL')),
  price_source   text not null check (price_source in ('TESOURO', 'ANBIMA', 'CVM', 'B3', 'COINGECKO', 'TIINGO', 'CURVE', 'MANUAL')),
  source_ref     text check (length(source_ref) <= 80),
  isin           text check (isin ~ '^[A-Z]{2}[A-Z0-9]{9}[0-9]$'),
  indexer        text check (indexer in ('PRE', 'CDI', 'SELIC', 'IPCA', 'IGPM')),
  index_pct      numeric(7,3) check (index_pct > 0 and index_pct <= 1000),
  rate_pct       numeric(9,5) check (rate_pct > -100 and rate_pct < 1000),
  issue_date     date,
  maturity_date  date,
  face_value     numeric(24,8) check (face_value > 0),
  liquidity      text check (liquidity in ('D0', 'D1_D30', 'D31_D180', 'ABOVE_180', 'MATURITY')),
  strategy       text check (strategy in ('POS_FIXADO', 'INFLACAO', 'PRE_FIXADO', 'MULTIMERCADO', 'ACOES', 'IMOBILIARIO',
                                          'INTERNACIONAL', 'ALTERNATIVOS', 'PREVIDENCIA', 'CRIPTO')),
  tax_exempt     boolean not null default false,
  tracked        boolean not null default false, -- held by some client: the price jobs fetch it
  created_by     uuid,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  check ((pricing = 'CURVE') = (price_source = 'CURVE')),
  check (pricing <> 'CURVE' or (indexer is not null and issue_date is not null)),
  check (maturity_date is null or issue_date is null or maturity_date > issue_date),
  check ((office_id is null) = (price_source not in ('CURVE', 'MANUAL')))
);
create unique index instruments_code_platform on cw_nonprod.instruments (code) where office_id is null;
create unique index instruments_code_office on cw_nonprod.instruments (office_id, code) where office_id is not null;
create index instruments_isin on cw_nonprod.instruments (isin) where isin is not null;
create index instruments_tracked on cw_nonprod.instruments (price_source) where tracked;
create index instruments_search on cw_nonprod.instruments (kind, code);

create function cw_nonprod_private.can_see_instrument(p_instrument uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce((select i.office_id is null and cw_nonprod_private.my_role() is not null
                       or i.office_id = cw_nonprod_private.my_office() or cw_nonprod_private.support_access(i.office_id)
                     from cw_nonprod.instruments i where i.id = p_instrument), false)
$$;

-- ---------------------------------------------------------------- prices, indices and corporate actions
create table cw_nonprod.instrument_prices (
  instrument_id uuid not null references cw_nonprod.instruments (id) on delete cascade,
  price_date    date not null check (price_date >= '1990-01-01'),
  price         numeric(24,8) not null check (price > 0),
  source        text not null check (source in ('TESOURO', 'ANBIMA', 'CVM', 'B3', 'COINGECKO', 'TIINGO', 'MANUAL')),
  rate_pct      numeric(9,5),
  entered_by    uuid,
  fetched_at    timestamptz not null default now(),
  primary key (instrument_id, price_date)
);

create table cw_nonprod.index_values (
  index_code text not null check (index_code in ('CDI', 'SELIC', 'IPCA', 'IGPM')),
  ref_date   date not null,   -- business day (CDI, SELIC: % a.d.) or first day of the reference month (IPCA, IGP-M: % a.m.)
  value      numeric(12,8) not null check (value > -100 and value < 100),
  source     text not null default 'BCB_SGS' check (length(source) <= 40),
  fetched_at timestamptz not null default now(),
  primary key (index_code, ref_date),
  check (index_code in ('CDI', 'SELIC') or extract(day from ref_date) = 1)
);

create table cw_nonprod.instrument_events (
  id            uuid primary key default gen_random_uuid(),
  instrument_id uuid not null references cw_nonprod.instruments (id) on delete cascade,
  kind          text not null check (kind in ('CASH', 'FACTOR')),
  label         text not null check (length(label) between 1 and 60),
  com_date      date not null,          -- last date "com" (holders at its close are entitled)
  pay_date      date,
  value         numeric(24,12) not null check (value > 0),  -- net cash per unit (CASH) or quantity factor (FACTOR)
  source        text not null check (source in ('B3', 'TIINGO')),
  -- ACTIVE events are applied to every holder automatically; SUGGESTED ones wait for the consultant (stock events
  -- whose factor convention varies at the source).
  status        text not null check (status in ('ACTIVE', 'SUGGESTED')),
  fetched_at    timestamptz not null default now(),
  unique (instrument_id, kind, label, com_date, value)
);

create table cw_nonprod.price_jobs (
  id          bigint generated always as identity primary key,
  source      text not null check (length(source) <= 40),
  ran_at      timestamptz not null default now(),
  ok          boolean not null,
  ref_date    date,
  rows_stored integer not null default 0,
  message     text check (length(message) <= 1000),
  file_sha256 char(64) check (file_sha256 ~ '^[0-9a-f]{64}$')
);
create index price_jobs_recent on cw_nonprod.price_jobs (source, ran_at desc);

-- ---------------------------------------------------------------- client movements and settings
create table cw_nonprod.portfolio_transactions (
  id               uuid primary key default gen_random_uuid(),
  client_id        uuid not null references cw_nonprod.clients (id) on delete cascade,
  instrument_id    uuid not null references cw_nonprod.instruments (id),
  account_id       uuid references cw_nonprod.financial_accounts (id),
  institution_id   uuid references cw_nonprod.financial_institutions (id),
  holder_member_id uuid,
  trade_date       date not null check (trade_date >= '1990-01-01'),
  kind             text not null check (kind in ('INITIAL', 'BUY', 'SELL', 'INCOME', 'AMORTIZATION', 'SPLIT', 'QTY_ADJUST')),
  quantity         numeric(28,10),
  price            numeric(24,8) check (price > 0),
  amount           numeric(18,2) check (amount > 0),
  factor           numeric(18,10) check (factor > 0),
  notes            text check (length(notes) <= 500),
  source           text not null default 'MANUAL' check (source in ('MANUAL', 'SPREADSHEET', 'STATEMENT')),
  batch_id         uuid,
  created_by       uuid,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  archived_at      timestamptz,
  archived_by      uuid,
  check (kind not in ('INITIAL', 'BUY', 'SELL') or (quantity > 0 and (price is not null or amount is not null))),
  check (kind not in ('INCOME', 'AMORTIZATION') or amount is not null),
  check (kind <> 'SPLIT' or factor is not null),
  check (kind <> 'QTY_ADJUST' or (quantity is not null and quantity <> 0)),
  foreign key (holder_member_id, client_id) references cw_nonprod.family_members (id, client_id)
);
create index portfolio_tx_client on cw_nonprod.portfolio_transactions (client_id, trade_date) where archived_at is null;
create index portfolio_tx_instrument on cw_nonprod.portfolio_transactions (instrument_id) where archived_at is null;
create trigger t_client_immutable before update on cw_nonprod.portfolio_transactions for each row execute function cw_nonprod_private.forbid_client_change();

create table cw_nonprod.portfolio_settings (
  client_id        uuid primary key references cw_nonprod.clients (id) on delete cascade,
  benchmark_index  text not null default 'CDI' check (benchmark_index in ('CDI', 'SELIC', 'IPCA', 'IGPM', 'PRE', 'NONE')),
  benchmark_pct    numeric(7,3) not null default 100 check (benchmark_pct > 0 and benchmark_pct <= 1000),
  benchmark_spread numeric(7,3) not null default 0 check (benchmark_spread > -50 and benchmark_spread < 100),
  updated_by       uuid,
  updated_at       timestamptz not null default now()
);

-- The office's recommended asset strategy per suitability profile (percent per strategy, summing to 100).
create table cw_nonprod.allocation_models (
  office_id  uuid not null references cw_nonprod.offices (id) on delete cascade,
  profile    text not null check (profile in ('CONSERVADOR', 'MODERADO', 'ARROJADO')),
  weights    jsonb not null check (jsonb_typeof(weights) = 'object' and length(weights::text) <= 2000),
  notes      text check (length(notes) <= 1000),
  updated_by uuid,
  updated_at timestamptz not null default now(),
  primary key (office_id, profile)
);

-- ---------------------------------------------------------------- RLS, grants, audit
alter table cw_nonprod.instruments enable row level security;
alter table cw_nonprod.instruments force row level security;
create policy instruments_read on cw_nonprod.instruments for select to authenticated
  using ((office_id is null and (select cw_nonprod_private.my_role()) is not null) or office_id = (select cw_nonprod_private.my_office()) or (select cw_nonprod_private.support_access(office_id)));

alter table cw_nonprod.instrument_prices enable row level security;
alter table cw_nonprod.instrument_prices force row level security;
create policy instrument_prices_read on cw_nonprod.instrument_prices for select to authenticated using ((select cw_nonprod_private.can_see_instrument(instrument_id)));

alter table cw_nonprod.instrument_events enable row level security;
alter table cw_nonprod.instrument_events force row level security;
create policy instrument_events_read on cw_nonprod.instrument_events for select to authenticated using ((select cw_nonprod_private.can_see_instrument(instrument_id)));

alter table cw_nonprod.index_values enable row level security;
alter table cw_nonprod.index_values force row level security;
create policy index_values_read on cw_nonprod.index_values for select to authenticated using ((select cw_nonprod_private.my_role()) is not null);

alter table cw_nonprod.price_jobs enable row level security;
alter table cw_nonprod.price_jobs force row level security;
create policy price_jobs_read on cw_nonprod.price_jobs for select to authenticated using ((select cw_nonprod_private.is_master()));

alter table cw_nonprod.portfolio_transactions enable row level security;
alter table cw_nonprod.portfolio_transactions force row level security;
create policy portfolio_transactions_read on cw_nonprod.portfolio_transactions for select to authenticated using ((select cw_nonprod_private.can_access_client(client_id)));

alter table cw_nonprod.portfolio_settings enable row level security;
alter table cw_nonprod.portfolio_settings force row level security;
create policy portfolio_settings_read on cw_nonprod.portfolio_settings for select to authenticated using ((select cw_nonprod_private.can_access_client(client_id)));

alter table cw_nonprod.allocation_models enable row level security;
alter table cw_nonprod.allocation_models force row level security;
create policy allocation_models_read on cw_nonprod.allocation_models for select to authenticated
  using (office_id = (select cw_nonprod_private.my_office()) or (select cw_nonprod_private.support_access(office_id)));

revoke all on cw_nonprod.instruments, cw_nonprod.instrument_prices, cw_nonprod.instrument_events, cw_nonprod.index_values, cw_nonprod.price_jobs,
  cw_nonprod.portfolio_transactions, cw_nonprod.portfolio_settings, cw_nonprod.allocation_models from public, anon, authenticated;
grant select on cw_nonprod.instruments, cw_nonprod.instrument_prices, cw_nonprod.instrument_events, cw_nonprod.index_values, cw_nonprod.price_jobs,
  cw_nonprod.portfolio_transactions, cw_nonprod.portfolio_settings, cw_nonprod.allocation_models to authenticated;
grant all on cw_nonprod.instruments, cw_nonprod.instrument_prices, cw_nonprod.instrument_events, cw_nonprod.index_values, cw_nonprod.price_jobs,
  cw_nonprod.portfolio_transactions, cw_nonprod.portfolio_settings, cw_nonprod.allocation_models to service_role;

-- Client data and office products are audited; market data (prices, indices, events, job log) is not personal data
-- and changes every day, so it is not.
create trigger t_audit after insert or update or delete on cw_nonprod.portfolio_transactions for each row execute function cw_nonprod_private.audit_row();
create trigger t_audit after insert or update or delete on cw_nonprod.portfolio_settings for each row execute function cw_nonprod_private.audit_row();
create trigger t_audit after insert or update or delete on cw_nonprod.allocation_models for each row execute function cw_nonprod_private.audit_row();

-- ---------------------------------------------------------------- staff RPCs
-- Instrument: official-source products are platform-wide and created once (an existing code is reused, never
-- overwritten by an office); curve and manual products belong to the caller's office.
create function cw_nonprod.invest_instrument_save(p_id uuid, p_data jsonb) returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  v_source text := p_data ->> 'price_source';
  v_code text := upper(regexp_replace(coalesce(p_data ->> 'code', ''), '\s', '', 'g'));
  v_office uuid := cw_nonprod_private.my_office();
  v_id uuid;
begin
  if not cw_nonprod_private.is_staff() then perform cw_nonprod_private.deny(); end if;
  if v_source is null then raise exception 'price_source required' using errcode = '22023'; end if;
  if (p_data ->> 'kind') in ('FUND', 'PENSION') and v_source = 'CVM' and v_code !~ '^[0-9]{14}$' then
    raise exception 'CNPJ must have 14 digits' using errcode = '22023';
  end if;
  if v_source in ('CURVE', 'MANUAL') then
    if exists (select 1 from cw_nonprod.instruments where office_id is null and code = v_code) then
      raise exception 'code already used by an official instrument' using errcode = '23505';
    end if;
    if p_id is null then
      insert into cw_nonprod.instruments (office_id, kind, subclass, code, name, issuer, currency, pricing, price_source, isin, indexer, index_pct,
        rate_pct, issue_date, maturity_date, face_value, liquidity, strategy, tax_exempt, created_by)
      values (v_office, p_data ->> 'kind', nullif(p_data ->> 'subclass', ''), v_code, btrim(p_data ->> 'name'), nullif(btrim(p_data ->> 'issuer'), ''),
        coalesce(p_data ->> 'currency', 'BRL'), case when v_source = 'CURVE' then 'CURVE' else 'MANUAL' end, v_source, nullif(p_data ->> 'isin', ''),
        nullif(p_data ->> 'indexer', ''), nullif(p_data ->> 'index_pct', '')::numeric, nullif(p_data ->> 'rate_pct', '')::numeric,
        nullif(p_data ->> 'issue_date', '')::date, nullif(p_data ->> 'maturity_date', '')::date, nullif(p_data ->> 'face_value', '')::numeric,
        nullif(p_data ->> 'liquidity', ''), nullif(p_data ->> 'strategy', ''), coalesce((p_data ->> 'tax_exempt')::boolean, false), auth.uid())
      returning id into v_id;
    else
      update cw_nonprod.instruments set kind = p_data ->> 'kind', subclass = nullif(p_data ->> 'subclass', ''), code = v_code, name = btrim(p_data ->> 'name'),
        issuer = nullif(btrim(p_data ->> 'issuer'), ''), currency = coalesce(p_data ->> 'currency', 'BRL'), isin = nullif(p_data ->> 'isin', ''),
        indexer = nullif(p_data ->> 'indexer', ''), index_pct = nullif(p_data ->> 'index_pct', '')::numeric, rate_pct = nullif(p_data ->> 'rate_pct', '')::numeric,
        issue_date = nullif(p_data ->> 'issue_date', '')::date, maturity_date = nullif(p_data ->> 'maturity_date', '')::date,
        face_value = nullif(p_data ->> 'face_value', '')::numeric, liquidity = nullif(p_data ->> 'liquidity', ''), strategy = nullif(p_data ->> 'strategy', ''),
        tax_exempt = coalesce((p_data ->> 'tax_exempt')::boolean, false), updated_at = now()
       where id = p_id and office_id = v_office
      returning id into v_id;
      if v_id is null then perform cw_nonprod_private.deny(); end if;
    end if;
    return v_id;
  end if;
  select id into v_id from cw_nonprod.instruments where office_id is null and code = v_code;
  if v_id is not null then return v_id; end if;
  insert into cw_nonprod.instruments (kind, subclass, code, name, issuer, currency, pricing, price_source, source_ref, isin, maturity_date, liquidity, strategy, created_by)
  values (p_data ->> 'kind', nullif(p_data ->> 'subclass', ''), v_code, btrim(p_data ->> 'name'), nullif(btrim(p_data ->> 'issuer'), ''),
    coalesce(p_data ->> 'currency', 'BRL'), 'MARKET', v_source, nullif(p_data ->> 'source_ref', ''), nullif(p_data ->> 'isin', ''),
    nullif(p_data ->> 'maturity_date', '')::date, nullif(p_data ->> 'liquidity', ''), nullif(p_data ->> 'strategy', ''), auth.uid())
  returning id into v_id;
  return v_id;
end $$;

-- Manual quotes of an office product (COE, offshore bond, unlisted fund…): up to 5.000 rows per call.
create function cw_nonprod.invest_manual_prices_save(p_instrument uuid, p_rows jsonb) returns integer
language plpgsql security definer set search_path = '' as $$
declare v_n integer;
begin
  if not cw_nonprod_private.is_staff() then perform cw_nonprod_private.deny(); end if;
  if not exists (select 1 from cw_nonprod.instruments where id = p_instrument and office_id = cw_nonprod_private.my_office() and pricing = 'MANUAL') then perform cw_nonprod_private.deny(); end if;
  if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) > 5000 then raise exception 'invalid rows' using errcode = '22023'; end if;
  insert into cw_nonprod.instrument_prices (instrument_id, price_date, price, source, entered_by)
  select p_instrument, (r ->> 'date')::date, (r ->> 'price')::numeric, 'MANUAL', auth.uid() from jsonb_array_elements(p_rows) r
  on conflict (instrument_id, price_date) do update set price = excluded.price, entered_by = excluded.entered_by, fetched_at = now();
  get diagnostics v_n = row_count;
  return v_n;
end $$;

create function cw_nonprod_private.invest_tx_write(p_client uuid, p_id uuid, p_data jsonb, p_source text, p_batch uuid) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_id uuid; v_inst uuid := (p_data ->> 'instrument_id')::uuid; v_acc uuid := nullif(p_data ->> 'account_id', '')::uuid;
begin
  if v_inst is null or not exists (select 1 from cw_nonprod.instruments i where i.id = v_inst and (i.office_id is null or i.office_id = cw_nonprod_private.my_office())) then
    raise exception 'unknown instrument' using errcode = '22023';
  end if;
  if v_acc is not null and not exists (select 1 from cw_nonprod.financial_accounts where id = v_acc and client_id = p_client and archived_at is null) then
    raise exception 'unknown account' using errcode = '22023';
  end if;
  if (p_data ->> 'trade_date')::date > current_date + 5 then raise exception 'trade date in the future' using errcode = '22023'; end if;
  if p_id is null then
    insert into cw_nonprod.portfolio_transactions (client_id, instrument_id, account_id, institution_id, holder_member_id, trade_date, kind, quantity, price,
      amount, factor, notes, source, batch_id, created_by)
    values (p_client, v_inst, v_acc, nullif(p_data ->> 'institution_id', '')::uuid, nullif(p_data ->> 'holder_member_id', '')::uuid,
      (p_data ->> 'trade_date')::date, p_data ->> 'kind', nullif(p_data ->> 'quantity', '')::numeric, nullif(p_data ->> 'price', '')::numeric,
      nullif(p_data ->> 'amount', '')::numeric, nullif(p_data ->> 'factor', '')::numeric, nullif(btrim(p_data ->> 'notes'), ''), p_source, p_batch, auth.uid())
    returning id into v_id;
  else
    update cw_nonprod.portfolio_transactions set instrument_id = v_inst, account_id = v_acc, institution_id = nullif(p_data ->> 'institution_id', '')::uuid,
      holder_member_id = nullif(p_data ->> 'holder_member_id', '')::uuid, trade_date = (p_data ->> 'trade_date')::date, kind = p_data ->> 'kind',
      quantity = nullif(p_data ->> 'quantity', '')::numeric, price = nullif(p_data ->> 'price', '')::numeric, amount = nullif(p_data ->> 'amount', '')::numeric,
      factor = nullif(p_data ->> 'factor', '')::numeric, notes = nullif(btrim(p_data ->> 'notes'), ''), updated_at = now()
     where id = p_id and client_id = p_client and archived_at is null
    returning id into v_id;
    if v_id is null then perform cw_nonprod_private.deny(); end if;
  end if;
  update cw_nonprod.instruments set tracked = true where id = v_inst and not tracked;
  return v_id;
end $$;
revoke all on function cw_nonprod_private.invest_tx_write(uuid, uuid, jsonb, text, uuid) from public, anon, authenticated;

-- Movements: staff only (consultant, assistant, admin with access to the client); the client portal is read-only.
create function cw_nonprod.invest_tx_save(p_client uuid, p_id uuid, p_data jsonb) returns uuid
language plpgsql security definer set search_path = '' as $$
begin
  if not cw_nonprod_private.is_staff() then perform cw_nonprod_private.deny(); end if;
  perform cw_nonprod_private.require_client(p_client);
  return cw_nonprod_private.invest_tx_write(p_client, p_id, p_data, 'MANUAL', null);
end $$;

-- Spreadsheet / statement import: all rows or none (one batch id), up to 2.000 rows.
create function cw_nonprod.invest_tx_import(p_client uuid, p_rows jsonb, p_source text default 'SPREADSHEET') returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_batch uuid := gen_random_uuid(); r jsonb;
begin
  if not cw_nonprod_private.is_staff() then perform cw_nonprod_private.deny(); end if;
  perform cw_nonprod_private.require_client(p_client);
  if p_source not in ('SPREADSHEET', 'STATEMENT') then raise exception 'invalid source' using errcode = '22023'; end if;
  if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) not between 1 and 2000 then raise exception 'invalid rows' using errcode = '22023'; end if;
  for r in select * from jsonb_array_elements(p_rows) loop
    perform cw_nonprod_private.invest_tx_write(p_client, null, r, p_source, v_batch);
  end loop;
  return v_batch;
end $$;

create function cw_nonprod.invest_tx_archive(p_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare v_client uuid;
begin
  if not cw_nonprod_private.is_staff() then perform cw_nonprod_private.deny(); end if;
  select client_id into v_client from cw_nonprod.portfolio_transactions where id = p_id and archived_at is null;
  perform cw_nonprod_private.require_client(v_client);
  update cw_nonprod.portfolio_transactions set archived_at = now(), archived_by = auth.uid() where id = p_id;
end $$;

create function cw_nonprod.invest_settings_save(p_client uuid, p_data jsonb) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not cw_nonprod_private.is_staff() then perform cw_nonprod_private.deny(); end if;
  perform cw_nonprod_private.require_client(p_client);
  insert into cw_nonprod.portfolio_settings as s (client_id, benchmark_index, benchmark_pct, benchmark_spread, updated_by)
  values (p_client, p_data ->> 'benchmark_index', coalesce(nullif(p_data ->> 'benchmark_pct', '')::numeric, 100),
    coalesce(nullif(p_data ->> 'benchmark_spread', '')::numeric, 0), auth.uid())
  on conflict (client_id) do update set benchmark_index = excluded.benchmark_index, benchmark_pct = excluded.benchmark_pct,
    benchmark_spread = excluded.benchmark_spread, updated_by = auth.uid(), updated_at = now();
end $$;

-- Office admin: recommended allocation per suitability profile. Weights are whole or decimal percents summing to 100.
create function cw_nonprod.allocation_model_save(p_profile text, p_weights jsonb, p_notes text default null) returns void
language plpgsql security definer set search_path = '' as $$
declare v_sum numeric;
begin
  if cw_nonprod_private.my_role() is distinct from 'ADMIN' or not cw_nonprod_private.staff_aal_ok() then perform cw_nonprod_private.deny(); end if;
  if jsonb_typeof(p_weights) <> 'object' or exists (select 1 from jsonb_each_text(p_weights) e
      where e.key not in ('POS_FIXADO', 'INFLACAO', 'PRE_FIXADO', 'MULTIMERCADO', 'ACOES', 'IMOBILIARIO', 'INTERNACIONAL', 'ALTERNATIVOS', 'PREVIDENCIA', 'CRIPTO')
         or e.value !~ '^\d{1,3}(\.\d{1,2})?$') then
    raise exception 'invalid weights' using errcode = '22023';
  end if;
  select coalesce(sum(value::numeric), 0) into v_sum from jsonb_each_text(p_weights);
  if v_sum <> 100 then raise exception 'weights must sum to 100' using errcode = '22023'; end if;
  insert into cw_nonprod.allocation_models as m (office_id, profile, weights, notes, updated_by)
  values (cw_nonprod_private.my_office(), p_profile, p_weights, nullif(btrim(p_notes), ''), auth.uid())
  on conflict (office_id, profile) do update set weights = excluded.weights, notes = excluded.notes, updated_by = auth.uid(), updated_at = now();
end $$;

-- Everything the portfolio page needs for one client in a single call (no row cap): instruments held, movements,
-- prices since the first movement, corporate actions, indices and PTAX. Same access as the client record.
create function cw_nonprod.invest_data(p_client uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare v_from date; v_insts uuid[];
begin
  if not cw_nonprod_private.can_access_client(p_client) then perform cw_nonprod_private.deny(); end if;
  select min(trade_date), array_agg(distinct instrument_id) into v_from, v_insts
    from cw_nonprod.portfolio_transactions where client_id = p_client and archived_at is null;
  if v_from is null then
    return jsonb_build_object('instruments', '[]'::jsonb, 'transactions', '[]'::jsonb, 'prices', '{}'::jsonb, 'events', '[]'::jsonb,
      'indices', '{}'::jsonb, 'fx', '{}'::jsonb, 'settings', (select to_jsonb(s) from cw_nonprod.portfolio_settings s where s.client_id = p_client));
  end if;
  v_from := least(v_from, coalesce((select min(issue_date) from cw_nonprod.instruments where id = any (v_insts)), v_from)) - 10;
  return jsonb_build_object(
    'instruments', (select coalesce(jsonb_agg(to_jsonb(i) - 'created_by'), '[]') from cw_nonprod.instruments i where i.id = any (v_insts)),
    'transactions', (select coalesce(jsonb_agg(to_jsonb(t) - 'created_by' - 'archived_by' order by t.trade_date, t.created_at), '[]')
                       from cw_nonprod.portfolio_transactions t where t.client_id = p_client and t.archived_at is null),
    'prices', (select coalesce(jsonb_object_agg(x.instrument_id, x.rows), '{}') from (
                 select p.instrument_id, jsonb_agg(jsonb_build_array(p.price_date, p.price) order by p.price_date) rows
                   from cw_nonprod.instrument_prices p where p.instrument_id = any (v_insts) and p.price_date >= v_from group by p.instrument_id) x),
    'events', (select coalesce(jsonb_agg(to_jsonb(e) - 'fetched_at'), '[]') from cw_nonprod.instrument_events e
                where e.instrument_id = any (v_insts) and e.com_date >= v_from),
    'indices', (select coalesce(jsonb_object_agg(x.index_code, x.rows), '{}') from (
                  select v.index_code, jsonb_agg(jsonb_build_array(v.ref_date, v.value) order by v.ref_date) rows
                    from cw_nonprod.index_values v
                   where (v.index_code in ('IPCA', 'IGPM') and v.ref_date >= '2000-07-01')
                      or (v.index_code = 'CDI' and v.ref_date >= v_from)
                      or (v.index_code = 'SELIC' and v.ref_date >= case when exists (select 1 from cw_nonprod.instruments i where i.id = any (v_insts) and i.code like 'LFT%') then '2000-07-01'::date else v_from end)
                   group by v.index_code) x),
    'fx', (select coalesce(jsonb_object_agg(x.currency, x.rows), '{}') from (
             select f.currency, jsonb_agg(jsonb_build_array(f.rate_date, f.rate) order by f.rate_date) rows
               from cw_nonprod.fx_rates f where f.rate_date >= v_from group by f.currency) x),
    'settings', (select to_jsonb(s) from cw_nonprod.portfolio_settings s where s.client_id = p_client)
  );
end $$;

-- Instrument search for the trade ticket (platform-wide plus the caller's office products).
create function cw_nonprod.invest_instrument_search(p_query text, p_kind text default null) returns setof cw_nonprod.instruments
language sql stable security definer set search_path = '' as $$
  select i.* from cw_nonprod.instruments i
   where cw_nonprod_private.is_staff() and (i.office_id is null or i.office_id = cw_nonprod_private.my_office())
     and (p_kind is null or i.kind = p_kind)
     and length(btrim(p_query)) >= 2
     and (i.code ilike '%' || replace(replace(btrim(p_query), '%', ''), '_', '') || '%'
          or i.name ilike '%' || replace(replace(btrim(p_query), '%', ''), '_', '') || '%'
          or i.isin = upper(btrim(p_query)))
   order by (i.code = upper(btrim(p_query))) desc, i.tracked desc, i.code
   limit 25
$$;

-- ---------------------------------------------------------------- service RPCs (price jobs, server only)
create function cw_nonprod.service_index_upsert(p_code text, p_rows jsonb) returns integer
language plpgsql security definer set search_path = '' as $$
declare v_n integer;
begin
  insert into cw_nonprod.index_values (index_code, ref_date, value)
  select p_code, (r ->> 'date')::date, (r ->> 'value')::numeric from jsonb_array_elements(p_rows) r
  on conflict (index_code, ref_date) do update set value = excluded.value, fetched_at = now()
   where cw_nonprod.index_values.value is distinct from excluded.value;
  get diagnostics v_n = row_count;
  return v_n;
end $$;

-- PTAX history from the SGS series (BRL per unit, selling rate): rows [{date, value}].
create function cw_nonprod.service_fx_upsert(p_currency text, p_rows jsonb) returns integer
language plpgsql security definer set search_path = '' as $$
declare v_n integer;
begin
  insert into cw_nonprod.fx_rates (currency, rate_date, rate, source)
  select p_currency, (r ->> 'date')::date, (r ->> 'value')::numeric, 'BCB_SGS' from jsonb_array_elements(p_rows) r
  on conflict (currency, rate_date) do nothing;
  get diagnostics v_n = row_count;
  return v_n;
end $$;

-- Rows: [{code, name, kind, subclass?, isin?, maturity?, currency?, date, price, rate?}]. Creates missing platform
-- instruments (registry) and stores prices: for every instrument when p_all, otherwise only for tracked ones.
-- Source priority per day: ANBIMA (market reference) over the Tesouro Direto price for the same bond.
create function cw_nonprod.service_prices_upsert(p_source text, p_rows jsonb, p_all boolean default false) returns integer
language plpgsql security definer set search_path = '' as $$
declare v_n integer;
begin
  if p_source not in ('TESOURO', 'ANBIMA', 'CVM', 'B3', 'COINGECKO', 'TIINGO') then raise exception 'invalid source' using errcode = '22023'; end if;
  insert into cw_nonprod.instruments (kind, subclass, code, name, currency, pricing, price_source, isin, maturity_date, liquidity, strategy)
  select distinct on (r ->> 'code') r ->> 'kind', nullif(r ->> 'subclass', ''), r ->> 'code', left(coalesce(nullif(btrim(r ->> 'name'), ''), r ->> 'code'), 160),
    coalesce(r ->> 'currency', 'BRL'), 'MARKET', p_source, nullif(r ->> 'isin', ''), nullif(r ->> 'maturity', '')::date,
    nullif(r ->> 'liquidity', ''), nullif(r ->> 'strategy', '')
    from jsonb_array_elements(p_rows) r where r ? 'kind'
  on conflict (code) where office_id is null do update set
    name = case when cw_nonprod.instruments.price_source = excluded.price_source then excluded.name else cw_nonprod.instruments.name end,
    isin = coalesce(cw_nonprod.instruments.isin, excluded.isin), updated_at = now()
   where cw_nonprod.instruments.name is distinct from excluded.name or cw_nonprod.instruments.isin is null;
  insert into cw_nonprod.instrument_prices (instrument_id, price_date, price, source, rate_pct)
  select i.id, (r ->> 'date')::date, (r ->> 'price')::numeric, p_source, nullif(r ->> 'rate', '')::numeric
    from jsonb_array_elements(p_rows) r join cw_nonprod.instruments i on i.office_id is null and i.code = r ->> 'code'
   where (p_all or i.tracked) and r ? 'price'
  on conflict (instrument_id, price_date) do update set price = excluded.price, source = excluded.source, rate_pct = excluded.rate_pct, fetched_at = now()
   where not (cw_nonprod.instrument_prices.source = 'ANBIMA' and excluded.source = 'TESOURO')
     and cw_nonprod.instrument_prices.source <> 'MANUAL'
     and (cw_nonprod.instrument_prices.price is distinct from excluded.price or cw_nonprod.instrument_prices.source <> excluded.source);
  get diagnostics v_n = row_count;
  return v_n;
end $$;

-- Rows: [{code? | isin?, kind, label, com_date, pay_date?, value, status}].
create function cw_nonprod.service_events_upsert(p_source text, p_rows jsonb) returns integer
language plpgsql security definer set search_path = '' as $$
declare v_n integer;
begin
  insert into cw_nonprod.instrument_events (instrument_id, kind, label, com_date, pay_date, value, source, status)
  select distinct on (i.id, r ->> 'kind', r ->> 'label', r ->> 'com_date', r ->> 'value')
         i.id, r ->> 'kind', left(r ->> 'label', 60), (r ->> 'com_date')::date, nullif(r ->> 'pay_date', '')::date, (r ->> 'value')::numeric, p_source, r ->> 'status'
    from jsonb_array_elements(p_rows) r
    join cw_nonprod.instruments i on i.office_id is null and (i.code = r ->> 'code' or (r ? 'isin' and i.isin = r ->> 'isin'))
   where i.tracked
  on conflict (instrument_id, kind, label, com_date, value) do update set pay_date = excluded.pay_date, fetched_at = now();
  get diagnostics v_n = row_count;
  return v_n;
end $$;

create function cw_nonprod.service_price_job_log(p_source text, p_ok boolean, p_ref date, p_rows integer, p_message text, p_sha text) returns void
language sql security definer set search_path = '' as $$
  insert into cw_nonprod.price_jobs (source, ok, ref_date, rows_stored, message, file_sha256)
  values (p_source, p_ok, p_ref, coalesce(p_rows, 0), left(p_message, 1000), p_sha);
  delete from cw_nonprod.price_jobs where ran_at < now() - interval '180 days';
$$;

-- What the jobs must fetch: tracked platform instruments of a source, with the first date anyone holds them.
create function cw_nonprod.service_tracked_instruments(p_source text) returns jsonb
language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', i.id, 'code', i.code, 'source_ref', i.source_ref, 'isin', i.isin, 'kind', i.kind,
    'since', (select min(t.trade_date) from cw_nonprod.portfolio_transactions t where t.instrument_id = i.id and t.archived_at is null),
    'last', (select max(p.price_date) from cw_nonprod.instrument_prices p where p.instrument_id = i.id))), '[]')
    from cw_nonprod.instruments i where i.office_id is null and i.tracked and i.price_source = p_source
$$;

-- Platform owner: health of every price source (last run, last success, failures in the last 7 days, stale tracked).
create function cw_nonprod.master_price_health() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not cw_nonprod_private.is_master() then perform cw_nonprod_private.deny(); end if;
  return jsonb_build_object(
    'jobs', (select coalesce(jsonb_agg(x order by x.source), '[]') from (
      select j.source, max(j.ran_at) last_run, max(j.ran_at) filter (where j.ok) last_ok, max(j.ref_date) filter (where j.ok) last_ref,
             count(*) filter (where not j.ok and j.ran_at > now() - interval '7 days') failures_7d,
             (array_agg(j.message order by j.ran_at desc))[1] last_message
        from cw_nonprod.price_jobs j group by j.source) x),
    'indices', (select coalesce(jsonb_object_agg(index_code, last), '{}') from (select index_code, max(ref_date) last from cw_nonprod.index_values group by index_code) y),
    'stale', (select coalesce(jsonb_agg(jsonb_build_object('code', i.code, 'source', i.price_source, 'last', p.last) order by p.last nulls first), '[]') from cw_nonprod.instruments i
               left join lateral (select max(price_date) last from cw_nonprod.instrument_prices where instrument_id = i.id) p on true
              where i.office_id is null and i.tracked and (p.last is null or p.last < current_date - 5)),
    'tracked', (select count(*) from cw_nonprod.instruments where tracked)
  );
end $$;

revoke all on function cw_nonprod.invest_instrument_save(uuid, jsonb), cw_nonprod.invest_manual_prices_save(uuid, jsonb), cw_nonprod.invest_tx_save(uuid, uuid, jsonb),
  cw_nonprod.invest_tx_import(uuid, jsonb, text), cw_nonprod.invest_tx_archive(uuid), cw_nonprod.invest_settings_save(uuid, jsonb), cw_nonprod.allocation_model_save(text, jsonb, text),
  cw_nonprod.invest_data(uuid), cw_nonprod.invest_instrument_search(text, text), cw_nonprod.master_price_health(),
  cw_nonprod.service_index_upsert(text, jsonb), cw_nonprod.service_prices_upsert(text, jsonb, boolean), cw_nonprod.service_events_upsert(text, jsonb),
  cw_nonprod.service_price_job_log(text, boolean, date, integer, text, text), cw_nonprod.service_tracked_instruments(text), cw_nonprod_private.can_see_instrument(uuid),
  cw_nonprod.service_fx_upsert(text, jsonb)
  from public, anon, authenticated;
grant execute on function cw_nonprod.invest_instrument_save(uuid, jsonb), cw_nonprod.invest_manual_prices_save(uuid, jsonb), cw_nonprod.invest_tx_save(uuid, uuid, jsonb),
  cw_nonprod.invest_tx_import(uuid, jsonb, text), cw_nonprod.invest_tx_archive(uuid), cw_nonprod.invest_settings_save(uuid, jsonb), cw_nonprod.allocation_model_save(text, jsonb, text),
  cw_nonprod.invest_data(uuid), cw_nonprod.invest_instrument_search(text, text), cw_nonprod.master_price_health(), cw_nonprod_private.can_see_instrument(uuid) to authenticated;
grant execute on function cw_nonprod.service_index_upsert(text, jsonb), cw_nonprod.service_prices_upsert(text, jsonb, boolean), cw_nonprod.service_events_upsert(text, jsonb),
  cw_nonprod.service_price_job_log(text, boolean, date, integer, text, text), cw_nonprod.service_tracked_instruments(text), cw_nonprod.service_fx_upsert(text, jsonb) to service_role;

-- ---------------------------------------------------------------- "Investimentos" becomes a per-client module (on by default)
alter table cw_nonprod.clients drop constraint clients_modules_check;
alter table cw_nonprod.clients add constraint clients_modules_check
  check (modules <@ array['TRANSACTIONS', 'WEALTH', 'CASHFLOW', 'GOALS', 'SUCCESSION', 'PROTECTION', 'TAX', 'REPORT', 'INVESTMENTS']);
alter table cw_nonprod.clients alter column modules set default array['TRANSACTIONS', 'WEALTH', 'CASHFLOW', 'GOALS', 'SUCCESSION', 'PROTECTION', 'TAX', 'REPORT', 'INVESTMENTS'];
update cw_nonprod.clients set modules = modules || array['INVESTMENTS'] where not ('INVESTMENTS' = any (modules));
commit;
select 'migração 32 ok' as resultado, to_regclass('cw_nonprod.instruments') is not null as ativos, to_regclass('cw_nonprod.portfolio_transactions') is not null as movimentacoes, (select count(*) from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'cw_nonprod' and c.relname in ('instruments','instrument_prices','instrument_events','index_values','price_jobs','portfolio_transactions','portfolio_settings','allocation_models') and not c.relrowsecurity) as sem_rls;
